+        margin: 1rem 0 2rem;
+        color: var(--muted);
+      }
+
+      form {
+        display: grid;
+        gap: 1.1rem;
+      }
+
+      .form-field {
+        display: grid;
+        gap: 0.45rem;
+      }
+
+      label {
+        font-weight: 700;
+      }
+
+      .required {
+        color: var(--accent);
+      }
+
+      input {
+        width: 100%;
+        min-height: 3.1rem;
+        padding: 0.85rem 1rem;
+        border: 1px solid var(--panel-border);
+        border-radius: 0.85rem;
+        background: var(--input);
+        color: var(--text);
+        font: inherit;
+        transition: border-color 160ms ease, box-shadow 160ms ease, background 160ms ease;
+      }
+
+      input::placeholder {
+        color: #7d8b9d;
+      }
+
