           radial-gradient(circle at top left, rgba(88, 166, 255, 0.22), transparent 34rem),
           linear-gradient(135deg, #080b10 0%, var(--bg) 52%, #101620 100%);
         color: var(--text);
         font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
         line-height: 1.5;
       }

       .support-card {
         width: min(100%, 34rem);
         padding: clamp(1.5rem, 5vw, 2.5rem);
