       const fields = [
         {
           id: "full-name",
           name: "fullName",
           label: "Full name",
           type: "text",
           placeholder: "Jane Doe",
           autocomplete: "name",
           required: true
         },
         {
           id: "email",
           name: "email",
           label: "Email address",
           type: "email",
           placeholder: "jane@example.com",
           autocomplete: "email",
           required: true
         },
         {
           id: "phone",
           name: "phone",
           label: "Phone number",
           type: "tel",
           placeholder: "+1 555 123 4567",
           autocomplete: "tel",
           required: false,
           helperText: "Optional. Use international format, for example +1 555 123 4567."
         }
       ];

       function RequiredMarker({ required }) {
         return required ? '<span class="required" aria-hidden="true">*</span>' : "";
       }

       function FormField({ field }) {
         const helperId = field.helperText ? `${field.id}-helper` : "";
         const describedBy = helperId ? ` aria-describedby="${helperId}"` : "";
         const required = field.required ? " required" : "";

         return `
           <div class="form-field">
             <label for="${field.id}">
               ${field.label} ${RequiredMarker({ required: field.required })}
             </label>
             <input
               id="${field.id}"
               name="${field.name}"
               type="${field.type}"
               placeholder="${field.placeholder}"
               autocomplete="${field.autocomplete}"
               ${required}
               ${describedBy}
             >
             ${field.helperText ? `<p class="helper-text" id="${helperId}">${field.helperText}</p>` : ""}
           </div>
         `;
       }

       function ContactForm() {
         return `
           <section class="support-card">
             <p class="eyebrow">Support</p>
             <h1 id="support-form-title">Contact our team</h1>
             <p class="intro">Tell us who you are and how to reach you. Required fields are marked with an asterisk.</p>
             <form action="#" method="post" novalidate>
               ${fields.map((field) => FormField({ field })).join("")}
               <button type="submit">Submit request</button>
             </form>
           </section>
         `;
       }

       function App() {
         return ContactForm();
       }

       document.getElementById("root").innerHTML = App();
